file.specification:

// GameRoom class — one instance per active game session.

// STATE owned by GameRoom:
//   grid: Cell[][]                   — authoritative board
//   players: Player[]                — connected players
//   phase: GamePhase                 — IDLE | REFILLING | ROUND_END | HEIST_WINDOW
//   activePlayerId: string
//   unbanked: number
//   banked: Record<string, number>   — per player
//   multiplierStep: number           — 0-5
//   farklePool: number               — Rally/Heist only
//   vault: number                    — Heist only
//   roundNumber: number
//   globalMode: 'PRIME' | 'FRENZY'
//   playerEnergies: Record<string, number>
//   anchorPlayerId: string | null
//   sessionId: string                — UUID for analytics
//   chainCount: number               — increments per committed chain
//   serverSeed: string               — CSPRNG seed
//   combinedSeed: string | null      — set after all clientSeeds received
//   pool: SixPoolManager             — tile spawn pool

// MESSAGE HANDLERS:
//   SUBMIT_CHAIN: validate → scoreFarkle() → updateGrid() → cascade → broadcast
//     After scoring: call insertChainDecision() fire-and-forget
//     Enforce 100ms input lock per player (server-side anti-macro)
//   BANK: transfer unbanked → banked[playerId] → reset multiplier → ROUND_END
//     Call insertChainDecision() with decision: 'BANK'
//   PASS: (Rally) advance multiplier +1 if Conductor role → transfer to next player
//   VOTE_REACT: broadcast vote state to all players in room
//   INITIATE_HEIST: check dual threshold → start HEIST_WINDOW timer
//   LEAVE_ROOM: mark player disconnected, continue if others remain

// SKILL LOGGING (server-authoritative):
//   On every SUBMIT_CHAIN:
//     estimateFarkleRisk() from current pool state
//     isOptimalDecision() for the implicit CONTINUE decision
//     insertChainDecision() fire-and-forget
//   On BANK:
//     isOptimalDecision() for explicit BANK decision
//     insertChainDecision() fire-and-forget
//   On session end (all players disconnect or game over):
//     computeSkillScore() from session totals
//     insertSession() fire-and-forget

// PROVABLY FAIR:
//   On room creation: serverSeed = crypto.randomBytes(32).toString('hex')
//   serverSeedHash = SHA-256(serverSeed) — broadcast to all players on JOIN
//   On all clientSeeds received: combinedSeed = SHA-256(serverSeed + c1 + c2...)
//   SixPoolManager uses HMAC-SHA256 CSPRNG seeded from combinedSeed
//   On game end: broadcast SEED_REVEAL with serverSeed

// ROUND RESET (VS/Rally/Heist):
//   After all players complete a round:
//   Clear dice, refill from fresh pool draw
//   Rock/Lock blocker positions preserved
//   Banked scores persist
//   Round counter increments, unbanked resets to 0

// ENERGY (server mirror of useEnergy):
//   Server tracks playerEnergies[] and globalMode
//   On each SUBMIT_CHAIN: applyChainEnergy() to active player
//   Server broadcasts ENERGY_UPDATE after each chain
//   globalMode switches when any player crosses FRENZY_THRESHOLD
//   In FRENZY: server enforces first-write-wins on simultaneous chains
//     (timestamp comparison, 100ms input lock)

// CASCADE:
//   Runs as async loop using setTimeout recursion at 80ms intervals
//   Each step: stepGravity() → spawnTiles(pool) → normalizeTiles()
//   Broadcasts BOARD_UPDATE after each step
//   Dead board check after cascade complete: hasValidChain(grid)
//   If dead: pool.reshuffle() → respawn → re-check

// TURN TIMER:
//   setTimeout handle stored per room
//   On expiry: AUTO-BANK fires (protects unbanked, ends turn gracefully)
//   Cleared on every valid SUBMIT_CHAIN, BANK, PASS from active player

// DATABASE:
//   sql.js for local room state (rooms table, players table)
//   Supabase analytics.ts for skill data (fire-and-forget, never blocks)
